## Arrays

```js
const arr = [10, 20, 30];

// for...of — best for simple iteration (ES6)
for (const val of arr) console.log(val);

// forEach — side effects only, no break/continue
arr.forEach((val, i) => console.log(i, val));

// Classic for — when you need the index or early exit
for (let i = 0; i < arr.length; i++) { /* ... */ }

// Transformations
const doubled = arr.map(n => n * 2);
const big     = arr.filter(n => n > 10);
const sum     = arr.reduce((acc, n) => acc + n, 0);
```

## Objects

```js
const obj = { a: 1, b: 2, c: 3 };

// for...in (includes inherited — use carefully)
for (const key in obj) {
  if (Object.prototype.hasOwnProperty.call(obj, key)) {
    console.log(key, obj[key]);
  }
}

// Object.keys / values / entries — own, enumerable only
Object.keys(obj).forEach(key => console.log(key));
Object.values(obj).forEach(val => console.log(val));
Object.entries(obj).forEach(([key, val]) => console.log(key, val));

// Transform an object:
const doubled = Object.fromEntries(
  Object.entries(obj).map(([k, v]) => [k, v * 2])
);
```

detailMdTr:
## Diziler

```js
const arr = [10, 20, 30];

// for...of — basit yineleme için en iyi (ES6)
for (const val of arr) console.log(val);

// forEach — yalnızca yan etkiler, break/continue yok
arr.forEach((val, i) => console.log(i, val));

// Klasik for — indeks gerektiğinde veya erken çıkış için
for (let i = 0; i < arr.length; i++) { /* ... */ }

// Dönüşümler
const doubled = arr.map(n => n * 2);
const big     = arr.filter(n => n > 10);
const sum     = arr.reduce((acc, n) => acc + n, 0);
```

## Nesneler

```js
const obj = { a: 1, b: 2, c: 3 };

// for...in (miras alınanları içerir — dikkatli kullanın)
for (const key in obj) {
  if (Object.prototype.hasOwnProperty.call(obj, key)) {
    console.log(key, obj[key]);
  }
}

// Object.keys / values / entries — yalnızca kendi, numaralandırılabilir
Object.keys(obj).forEach(key => console.log(key));
Object.values(obj).forEach(val => console.log(val));
Object.entries(obj).forEach(([key, val]) => console.log(key, val));

// Nesneyi dönüştür:
const doubled = Object.fromEntries(
  Object.entries(obj).map(([k, v]) => [k, v * 2])
);
```

